#!/usr/bin/env bash
cd /d/startup_dev/so_sorry/simple_ads/production_v2
NEG='Ambient: faint gut room-tone, no music. Exaggerated glossy 3D cartoon animation. no subtitles, no captions, no on-screen text.'
anim(){ local key="$1" label="$2" prompt="$3"; echo "### $label"; higgsfield generate create veo3_1 --image "./scenes/$key" --duration 8 --aspect_ratio 9:16 --quality high --prompt "$prompt $NEG" --wait --wait-timeout 15m --json 2>&1 | grep -o '"result_url": "[^"]*"' | head -1; }

anim s3_start.png S3 'Slow push-in on the carom-seed hero Ajwain in the foreground. ONLY Ajwain speaks and moves his mouth; he looks at camera and says in a feisty energetic Hindi voice, natural lip sync, line begins after a half-second pause: अकेला नहीं! मैं हूँ अजवाइन! पेट की हेविनेस से लड़ने आया हूँ! Amla and the Constipation King keep their mouths firmly CLOSED and stay SILENT, only reacting with expression.'
anim s4_start.png S4 'Slow push-in on the fennel hero Saunf in the foreground. ONLY Saunf speaks and moves his mouth; he looks at camera and says in a smooth cool confident Hindi voice, natural lip sync, line begins after a half-second pause: और मैं हूँ सौंफ! ब्लोटिंग के ख़िलाफ़ मैं भी टीम में हूँ! The other heroes and the King keep mouths firmly CLOSED and SILENT, reacting only.'
anim s5_start.png S5 'Slow push-in on the ancient myrobalan hero Haritaki, crackling with golden thunder. ONLY Haritaki speaks and moves his mouth; he booms in a deep powerful wise Hindi elder voice, natural lip sync, line begins after a half-second pause: मैं हूँ हरीतकी! आयुर्वेद की सबसे ट्रस्टेड हर्ब्स में से एक! The other heroes and the recoiling King keep mouths CLOSED and SILENT.'
anim s6_start.png S6 'The four herb heroes step forward triumphantly. Haritaki front-center speaks for the team in a bold rallying Hindi voice, natural lip sync, line begins after a half-second pause: हम सिर्फ़ चार नहीं! अब असली ताक़त देखो! The other three heroes raise their fists in support with mouths CLOSED; the tiny King cowers in the far background.'
anim s7_start.png S7 'Ten-plus glowing herbs swirl as golden light and merge into the radiant Clear Gut dropper bottle. A warm trustworthy male Hindi NARRATOR speaks in VOICEOVER — no character on screen moves their mouth, no visible talking — clear natural narration, line begins after a half-second pause: दस से ज़्यादा आयुर्वेदिक हर्ब्स की पावर, अब एक ही क्लियर गट ड्रॉप में।'
anim s8_start.png S8 'The happy bright stomach dances beside the glowing Clear Gut bottle. A warm confident male Hindi NARRATOR speaks in VOICEOVER — no character talking on screen, no visible mouth movement — line begins after a half-second pause: सिर्फ़ दस-पंद्रह ड्रॉप्स, सुबह और रात। पेट हल्का, दिन हल्का।'
echo "VIDEOS_V2_DONE"
